function ItemDetail({ item, domainTitle, onImageClick }) {
  return (
    <div className="pr-card">
      <div className="pr-item-eyebrow">ด้าน {domainTitle} · ข้อ {item.code}</div>
      <h2 className="pr-item-title">{item.title}</h2>

      <div className="pr-item-row">
        <ListChecks size={16} />
        <div>
          <strong>งานที่ปฏิบัติ (Tasks)</strong>
          <p>{item.task}</p>
        </div>
      </div>
      <div className="pr-item-row">
        <Target size={16} />
        <div>
          <strong>ผลลัพธ์ (Outcomes)</strong>
          <p>{item.outcome}</p>
        </div>
      </div>
      <div className="pr-item-row">
        <ShieldCheck size={16} />
        <div>
          <strong>ตัวชี้วัด (Indicators)</strong>
          <p>{item.indicator}</p>
        </div>
      </div>
      <div className="pr-item-row pr-item-result">
        <Sparkles size={16} />
        <div>
          <strong>ผลการดำเนินงาน</strong>
          <p>{item.result}</p>
        </div>
      </div>
      <div className="pr-item-row">
        <FileCheck2 size={16} />
        <div>
          <strong>ร่องรอยเอกสารหลักฐาน</strong>
          <p>{item.evidence}</p>
          {item.evidenceLinks && item.evidenceLinks.length > 0 && (
            <div className="pr-evidence-links">
              {item.evidenceLinks.map((ev, i) => (
                <a
                  key={i}
                  className="pr-evidence-link"
                  href={ev.url}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <LinkIcon size={13} /> {ev.label}
                </a>
              ))}
            </div>
          )}
          {item.evidenceImages && item.evidenceImages.length > 0 && (
            <div className="pr-challenge-gallery">
              {item.evidenceImages.map((img, i) => (
                <div className="pr-challenge-figure" key={i}>
                  <img src={img.src} alt={img.caption} onClick={() => onImageClick(img.src)} />
                  <span>{img.caption}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

